23: export function fetchRegionSortList($get, parentCode) {
24:   if (!parentCode) {
25:     return Promise.resolve([])
26:   }
27:   return $get('/system/region/list', { parentCode }).then((res) => {
28:     return (res.data || []).map((item) => ({
