52: export function findPortalCityDeptNode(rawNodes = []) {
53:   const nodes = Array.isArray(rawNodes) ? rawNodes : []
54:   if (!nodes.length) return null
55:   const topCity = nodes.find((node) => deptNodeType(node) === CITY_DEPT_TYPE)
56:   if (topCity) return topCity
