1: /**
2:  * 门户（首页 / 我的）功能接口层。
3:  *
4:  * 接口路径与入参参照「苏住房C」zhi2-mobile-shimin 的 src/api/*.js：
5:  *   - article.js / articleV1.js  -> /v2.0/article/richText/page、/v2.0/article/richText/{id}
6:  *   - system.js                  -> /v2.0/system/banner/page、/v2.0/system/msg/pageByRegion、
7:  *                                  /v2.0/system/msg/getByMsgIdNoPermissions/{msgId}、
8:  *                                  /v2.0/system/pageNavigation/page
9:  *   - msg.js                     -> /v2.0/msg/msg/page、/v2.0/msg/msg/msgNum、
10:  *                                  /v2.0/msg/msgRange/{id}、/v2.0/msg/msgRange/updateReadFlag
11:  *   - property.js                -> /v2.0/property/msg/page（app 公告）
12:  *   - security.js                -> /v2.0/security/ctAuth/profile、/v2.0/security/ctAuth/logout、
13:  *                                  /v2.0/security/ctUserRealName/getAuditByToken
14:  *   - 苏住房后端 service-expand  -> /v2.0/article/portal/getStudyList?tab=1..5（学习园地）
15:  *   - 苏住房后端 common-flowable -> /v2.0/flowable/task/taskCount、/v2.0/flowable/task/todoTaskList
16:  *
17:  * 本项目网关前缀为 /api（nginx 反代），故统一使用 /v2.0/... 路径，与防汛接口保持同源同头。
18:  * 分页接口返回「根级」 {total,rows,code,msg}（非 data 包裹），因此统一 raw:true 后手动解包。
19:  */
20: import { request } from '../utils/request'
21: 
22: export interface PageResult<T> { total: number; rows: T[] }
23: 
24: function queryString(params: Record<string, unknown> = {}): string {
25:   const q = new URLSearchParams()
26:   Object.entries(params).forEach(([k, v]) => {
27:     if (v !== undefined && v !== null && v !== '') q.set(k, String(v))
28:   })
29:   const s = q.toString()
30:   return s ? `?${s}` : ''
31: }
32: 
33: /** 统一解包分页响应：兼容根级 PageResult 与 {code,msg,data} 两种包裹 */
34: async function page<T>(path: string, params: Record<string, unknown> = {}): Promise<PageResult<T>> {
